import Head from 'next/head';

export const metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
};

async function getPosts() {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5', {
    cache: 'no-store', // SSR equivalent
  });
  return response.json();
}

export default async function HomePage() {
  const posts = await getPosts();
  const userAgent = typeof window !== 'undefined' ? navigator.userAgent : 'Server';
  const timestamp = new Date().toISOString();

  return (
    <>
      <Head>
        <title>Home - My Blog</title>
        <meta name="description" content="Welcome to my blog homepage" />
        <meta property="og:title" content="Home - My Blog" />
      </Head>

      <div>
        <h1>Welcome to My Blog</h1>
        <p>Server-side rendered at: {timestamp}</p>
        <p>Your user agent: {userAgent}</p>

        <h2>Recent Posts</h2>
        <ul>
          {posts.map(post => (
            <li key={post.id}>
              <a href={`/blog/${post.id}`}>{post.title}</a>
            </li>
          ))}
        </ul>

        <a href="/blog">
          <button>View All Posts</button>
        </a>
      </div>
    </>
  );
}

